            continue
        p = os.path.join(out, "changes", path)
        if not os.path.isfile(p):
            continue
        for l in open(p):
            if not l.strip():
                continue
            e = json.loads(l)
            if c["change"] == "modified" and e.get("actor") != actor:
                continue
            if e.get("type") == "result.record":
                recorded = 1
            elif e.get("type") == "node.add" and (e.get("payload") or {}).get("kind") == "Experiment":
                experiments += 1
